    summary: '66歳以上（または大量化学療法の適応がない 60〜65歳）の II〜IV期 MCL 560例（年齢中央値 70歳）で、導入と維持を別々に無作為化した。導入の比較では、CR 率は R-FC 40%、R-CHOP 34% で有意差はなかったが（片側 P=0.10）、R-FC は導入中の増悪（14% vs 5%）と初回寛解中の死亡（10% vs 4%）が多く、4年 OS が短かった（47% vs 62%、HR 1.50）。奏効例 316例を維持で無作為化し（主解析 274例）、リツキシマブ（増悪まで2か月ごと）はインターフェロン α より寛解期間を延ばし（4年時点の寛解維持 58% vs 29%、HR 0.55）、R-CHOP 奏効例では OS も改善した（4年 87% vs 63%）。7.6年の続報でも結果は保たれた。',
